package local.cleartv.mobile;
import android.content.Context;import java.io.*;import java.util.*;import org.json.*;
final class LgActions {
 static void syncApps(LgControl tv)throws Exception{if(Boolean.TRUE.equals(tv.evaluate("!!(ClearTV.LGApps&&ClearTV.LGApps.sync)"))){try{JSONArray rows=tv.installedApps();tv.evaluate("ClearTV.LGApps.sync("+rows.toString()+")");tv.evaluate("new Promise(function(resolve){ClearTV.Catalog.load(function(){if(ClearTV.refreshAppViews)ClearTV.refreshAppViews();resolve(true);});})");}catch(IOException unavailable){/* Public known-ID fallback remains available. */}}}
 static boolean handles(String action){return Arrays.asList("apply","apps","pins","open","remoteConnect","remoteKey","remoteText","installThemePack","familyProfiles").contains(action)||action.matches("iptv(Connect|Clear|Open|Summary|List|Categories|Details|Settings|SaveSettings|Refresh|ClearProgress|Progress|Play|Epg|History)");}
 static Object run(Context c,String ip,String action,JSONObject p)throws Exception{try(LgControl tv=new LgControl(c,ip)){
  if((action.equals("pins")||action.equals("open"))&&!Boolean.TRUE.equals(tv.evaluate("!!(window.ClearTV&&ClearTV.LGApps)")))throw new IOException("حدّث Morph TV LG Preview إلى 0.1.1 من زر تثبيت LG لإضافة التطبيقات المثبتة.");
  if(action.equals("apply"))return tv.json("ClearTV.applyRemoteConfig("+p.toString()+")");
  if(action.equals("apps")){syncApps(tv);return tv.json("new Promise(function(resolve){ClearTV.Catalog.load(function(){resolve(ClearTV.getRemoteState());});})");}
  if(action.equals("pins")){JSONArray pins=p.getJSONArray("pins");if(pins.length()>24)throw new IOException("Too many pins");return tv.json("ClearTV.LGApps.pins("+pins.toString()+")");}
  if(action.equals("open")){String id=p.optString("id");JSONObject result=(JSONObject)tv.json("ClearTV.LGApps.open("+JSONObject.quote(id)+")");if(!result.optBoolean("sent"))throw new IOException(result.optString("error","LG did not confirm app launch."));return result;}
  if(action.equals("remoteConnect")){syncApps(tv);return new JSONObject().put("ready",true).put("native",false).put("scope","داخل Morph TV على LG فقط · Developer Mode مطلوب");}
  if(action.equals("remoteKey")){String key=p.optString("key");if(!Arrays.asList("UP","DOWN","LEFT","RIGHT","ENTER","RETURN","HOME","PLAY","PAUSE","FAVORITE").contains(key))throw new IOException("LG system/volume control is not included.");return tv.json("ClearTV.Remote.key("+JSONObject.quote(key)+")");}
  if(action.equals("remoteText")){String text=p.optString("text");if(text.length()>500)throw new IOException("Text exceeds 500 characters");return tv.json("ClearTV.Remote.text("+JSONObject.quote(text)+")");}
  if(action.equals("familyProfiles")){String op=p.optString("operation","list");if(!Arrays.asList("list","select","create").contains(op))throw new IOException("Invalid profile operation");return tv.json("ClearTV.familyAction("+JSONObject.quote(op)+","+p.toString()+")");}
  if(action.equals("installThemePack")){String id=p.optString("id");if(!Arrays.asList("egypt","europe","hockey","sports","national","egypt-extra","saudi-royal","saudi-clubs").contains(id))throw new IOException("Unknown theme pack");JSONObject state=(JSONObject)tv.json("ClearTV.ThemePacks.command("+new JSONObject().put("id",id).put("action","download")+")");long until=System.currentTimeMillis()+180000;while(!state.optBoolean("installed")){if(state.optString("state").equals("error")||System.currentTimeMillis()>until)throw new IOException(state.optString("error").equals("plus_required")?"فعّل Morph TV Plus على التلفزيون نفسه من Settings ثم General settings ثم Morph TV Plus. تفعيل الموبايل وحده لا يفعّل التلفزيون.":"LG theme download was not confirmed. Check TV internet and storage.");Thread.sleep(400);state=(JSONObject)tv.json("ClearTV.ThemePacks.status("+JSONObject.quote(id)+")");}return state;}
  String media=Character.toLowerCase(action.charAt(4))+action.substring(5);JSONObject response=(JSONObject)tv.json("MorphMedia.action("+JSONObject.quote(media)+","+p.toString()+")");if(action.equals("iptvConnect")&&!p.optBoolean("publicMode",false)&&!p.optBoolean("restorePersonal",false))new Vault(c).put("iptv-profile",p.toString().getBytes("UTF-8"));if(action.equals("iptvClear"))new Vault(c).put("iptv-profile",new byte[0]);return response;
 }}
}
